class Solution {
public:
    std::vector<long long> distance(std::vector<int>& nums) {
        int n = nums.size();
        std::unordered_map<int, std::vector<int>> groups;
        for (int i = 0; i < n; ++i) groups[nums[i]].push_back(i);
        std::vector<long long> ans(n, 0);
        for (auto& [val, indices] : groups) {
            int m = indices.size();
            if (m == 1) continue;
            std::vector<long long> pref(m + 1, 0);
            for (int i = 0; i < m; ++i) pref[i + 1] = pref[i] + indices[i];
            for (int r = 0; r < m; ++r) {
                long long idx = indices[r];
                long long left = (long long)r * idx - pref[r];
                long long right = (pref[m] - pref[r + 1]) - (long long)(m - 1 - r) * idx;
                ans[idx] = left + right;
            }
        }
        return ans;
    }
};

class Solution {
    public long[] distance(int[] nums) {
        int n = nums.length;
        java.util.Map<Integer, java.util.List<Integer>> groups = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            groups.computeIfAbsent(nums[i], k -> new java.util.ArrayList<>()).add(i);
        }
        long[] ans = new long[n];
        for (java.util.List<Integer> indices : groups.values()) {
            int m = indices.size();
            if (m == 1) continue;
            long[] pref = new long[m + 1];
            for (int i = 0; i < m; i++) pref[i + 1] = pref[i] + indices.get(i);
            for (int r = 0; r < m; r++) {
                long idx = indices.get(r);
                long left = (long) r * idx - pref[r];
                long right = (pref[m] - pref[r + 1]) - (long) (m - 1 - r) * idx;
                ans[(int) idx] = left + right;
            }
        }
        return ans;
    }
}

var distance = function(nums) {
    const n = nums.length;
    const groups = new Map();
    for (let i = 0; i < n; i++) {
        if (!groups.has(nums[i])) groups.set(nums[i], []);
        groups.get(nums[i]).push(i);
    }
    const ans = new Array(n).fill(0);
    for (const indices of groups.values()) {
        const m = indices.length;
        if (m === 1) continue;
        const pref = new BigInt64Array(m + 1);
        for (let i = 0; i < m; i++) pref[i + 1] = pref[i] + BigInt(indices[i]);
        for (let r = 0; r < m; r++) {
            const idx = BigInt(indices[r]);
            const left = BigInt(r) * idx - pref[r];
            const right = (pref[m] - pref[r + 1]) - (BigInt(m - 1 - r)) * idx;
            ans[indices[r]] = Number(left + right);
        }
    }
    return ans;
};
